---@module 'hl'

-- You can make apps auto-start here

-- Relevant Hyprland wiki section: https://wiki.hyprland.org/Configuring/Keywords/#executing



-- Start ABDownloadManager on login


-- ActivityWatch: server + awatcher only



-- Start vinci short cut


-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("powerprofilesctl set performance")
    -- hl.exec_cmd("env DO_NOT_UNSET_QT_QPA_PLATFORMTHEME=1 DO_NOT_SET_DESKTOP_SETTINGS_UNAWARE=1 QT_QPA_PLATFORM=xcb megasync --minimized") -- disabled 2026-10-30
    -- hl.exec_cmd("env DO_NOT_UNSET_QT_QPA_PLATFORMTHEME=1 DO_NOT_SET_DESKTOP_SETTINGS_UNAWARE=1 QT_QPA_PLATFORM=xcb ABDownloadManager --minimized") -- disabled 2026-10-30
    hl.exec_cmd("kdeconnect-indicator")
    -- ActivityWatch: the package ships the server at /opt, not /usr/bin/aw-server
    hl.exec_cmd("/opt/activitywatch/aw-server-rust/aw-server-rust")
    hl.exec_cmd("aw-awatcher")
    hl.exec_cmd("vicinae server")
    hl.exec_cmd("systembus-notify") -- shows earlyoom "killed X" pop-ups (installed by ~/optimize.sh)
    -- Keeps the external display on the left of the laptop, reacting to
    -- plug/unplug events. Log: $XDG_RUNTIME_DIR/hypr-monitor-layout.log
    hl.exec_cmd("~/.config/hypr/custom/scripts/monitor-layout.sh")
end)
